const Ended = ({ data }) => {
    return (
      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <h1>Game Over</h1>
        {/* Zobrazení skóre každého hráče */}
        <div>
          <h2>Player scores:</h2>
          <ul style={{ listStyleType: 'none', padding: 0 }}>
            {data.score.map((record, index) => (
              <li key={index} style={{ marginBottom: '10px' }}>
                <strong>Player:</strong> {record.player} | <strong>Skóre:</strong> {record.score}
              </li>
            ))}
          </ul>
        </div>

        {/* Zobrazení délky domečku */}
        <p>
          <strong>Long home:</strong> {data.houseLength}
        </p>

        {/* Tlačítka */}
        <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', marginTop: '20px' }}>
          <button
            onClick={() => console.log('New game clicked')}
            style={{
              padding: '10px 20px',
              fontSize: '16px',
              backgroundColor: '#007bff',
              color: '#fff',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
            }}
          >
            New Game
          </button>
          <button
            onClick={() => console.log('Exit clicked')}
            style={{
              padding: '10px 20px',
              fontSize: '16px',
              backgroundColor: '#dc3545',
              color: '#fff',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
            }}
          >
            Exit
          </button>
        </div>
      </div>
    );
  };
